export async function acquireAdvisoryLocks(manager: EntityManager, keys: bigint[]): Promise<void> {
  const sorted = [...new Set(keys)].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  for (const key of sorted) {
    await acquireAdvisoryLock(manager, key);
  }
}
