23	
24	use crate::codec::{Map, Value, decode, encode};
25	use crate::error::{CodecError, TrustViolation};
26	use crate::seal::{AadContext, STRUCT_TAG_MAILBOX_PAYLOAD, build_aad};
27	use crate::suite::ecdsa::{EcdsaSignature, EcdsaSigner, EcdsaVerifier};
28	use crate::suite::hpke::{self, hpke_open, hpke_seal};
29	use crate::suite::x25519::{X25519Public, X25519Secret};
30	
31	use super::{bytes_fixed, req};
32	
33	/// The sender-signature domain separator: the signature covers
34	/// `[MAILBOX_SIG_DOMAIN, v, senderIdentityPk, payload]`.
35	const MAILBOX_SIG_DOMAIN: &str = "cipherbox/v2/mailbox-sig";
36	
37	/// An opened, sender-verified mailbox item.
38	#[derive(Debug, Clone, PartialEq, Eq)]
39	pub struct MailboxItem {
40	    /// The opaque application payload (the caller frames its meaning).
41	    pub payload: Vec<u8>,
42	    /// The verified sender identity key (anchor it against the contact code).
43	    pub sender_identity: EcdsaVerifier,
44	}
45	
46	/// The AAD context of a mailbox payload at version `v`. A mailbox item is
47	/// recipient-addressed, not node/scope/epoch-bound, so those fields are zero;
48	/// only `v` and the `mailbox-payload` tag are load-bearing.
49	fn mailbox_ctx(v: u64) -> AadContext {
50	    AadContext {
51	        v,
52	        id: [0; 16],
53	        scope: [0; 16],
54	        epoch: 0,
55	        struct_tag: STRUCT_TAG_MAILBOX_PAYLOAD,
56	    }
57	}
58	
59	/// The sender-signature preimage.
60	fn sig_preimage(v: u64, sender_pk: &[u8], payload: &[u8]) -> Vec<u8> {
61	    encode(&Value::Array(vec![
62	        Value::Text(MAILBOX_SIG_DOMAIN.to_string()),
63	        Value::Unsigned(v),
64	        Value::Bytes(sender_pk.to_vec()),
65	        Value::Bytes(payload.to_vec()),
66	    ]))
67	}
