69	/// Seal a mailbox payload to `recipient_enc_pub`. `ephemeral_scalar` is the
70	/// injected, fresh-per-call HPKE ephemeral secret (KATs pin it; production
71	/// callers source it from their entropy seam — reuse under one recipient is a
72	/// catastrophic break). The sender signs inside the seal. Returns the published
73	/// block bytes.
74	pub fn seal_mailbox_payload(
75	    recipient_enc_pub: &X25519Public,
76	    ephemeral_scalar: &[u8; 32],
77	    v: u64,
78	    sender_signer: &EcdsaSigner,
79	    payload: &[u8],
80	) -> Vec<u8> {
81	    let sender_pk = sender_signer.verifying_key().to_sec1();
82	    let mut preimage = sig_preimage(v, &sender_pk, payload);
83	    let sender_sig = sender_signer.sign_detcbor(&preimage);
84	    preimage.zeroize();
85	
86	    let mut inner_map = Map::new();
87	    inner_map.insert("payload", Value::Bytes(payload.to_vec()));
88	    inner_map.insert("senderIdentityPk", Value::Bytes(sender_pk.to_vec()));
89	    inner_map.insert("senderSig", Value::Bytes(sender_sig.to_compact().to_vec()));
90	    let mut inner = encode(&Value::Map(inner_map));
91	
92	    let info = build_aad(&mailbox_ctx(v));
93	    let sealed = hpke_seal(recipient_enc_pub, ephemeral_scalar, &info, &[], &inner);
94	    inner.zeroize();
95	
96	    let mut block = Map::new();
97	    block.insert("ct", Value::Bytes(sealed.ciphertext));
98	    block.insert("enc", Value::Bytes(sealed.enc.to_vec()));
99	    encode(&Value::Map(block))
100	}
