102	/// Open + verify a mailbox payload. HPKE-open under `recipient_secret` and the
103	/// reconstructed `mailbox-payload` info (a tamper, wrong recipient, or version
104	/// downgrade is [`TrustViolation::HpkeOpenFailed`]), then verify the sender's
105	/// ECDSA signature (a bad key, non-canonical signature, or mismatch is
106	/// [`TrustViolation::IdentitySignatureInvalid`]). A structurally ill-formed
107	/// block or plaintext is [`Malformed`](crate::error::Malformed).
108	pub fn open_mailbox_payload(
109	    recipient_secret: &X25519Secret,
110	    v: u64,
111	    block: &[u8],
112	) -> Result<MailboxItem, CodecError> {
113	    let block_value = decode(block)?;
114	    let block_map = block_value.as_map()?;
115	    let ct = req(block_map, "ct")?.as_bytes()?;
116	    let enc = bytes_fixed::<{ hpke::ENC_LEN }>(req(block_map, "enc")?, "enc")?;
117	
118	    let info = build_aad(&mailbox_ctx(v));
119	    let mut inner = hpke_open(recipient_secret, &enc, &info, &[], ct).map_err(CodecError::from)?;
120	    let result = verify_inner(&inner, v);
121	    inner.zeroize();
122	    result
123	}
124	
125	fn verify_inner(inner: &[u8], v: u64) -> Result<MailboxItem, CodecError> {
126	    let value = decode(inner)?;
127	    let map = value.as_map()?;
128	    let payload = req(map, "payload")?.as_bytes()?.to_vec();
129	    let sender_pk = req(map, "senderIdentityPk")?.as_bytes()?;
130	    let sig_bytes = req(map, "senderSig")?.as_bytes()?;
131	
132	    // A bad key encoding, a non-canonical signature, or a mismatch are all the
133	    // one trust check: the claimed sender did not author this item.
134	    let sender_identity =
135	        EcdsaVerifier::from_sec1(sender_pk).ok_or(TrustViolation::IdentitySignatureInvalid)?;
136	    let sig =
137	        EcdsaSignature::from_compact(sig_bytes).ok_or(TrustViolation::IdentitySignatureInvalid)?;
138	    let mut preimage = sig_preimage(v, sender_pk, &payload);
139	    let verified = sender_identity.verify_detcbor(&preimage, &sig);
140	    preimage.zeroize();
141	    if !verified {
142	        return Err(TrustViolation::IdentitySignatureInvalid.into());
143	    }
144	    Ok(MailboxItem {
145	        payload,
146	        sender_identity,
147	    })
148	}
