93	        /// The agreed override seed.
94	        seed: [u8; 32],
95	        /// The epoch it belongs to.
96	        epoch: u64,
97	    },
98	    /// A disagreement — surfaced to the host, never silently dropped.
99	    Abuse(AbuseEvent),
