102	/// Cross-check the owner-blob seed, the optional ascent-link seed, and the seed
103	/// that actually unsealed the read-body. All present sources must equal
104	/// `unseal_seed`; the first disagreement is an [`AbuseEvent`], otherwise the
105	/// agreed `{unseal_seed, epoch}` is [`OwnerEntry::Confirmed`] for the caller to
106	/// cache.
107	///
108	/// `unseal_seed` is the trusted anchor — it is the seed that demonstrably
109	/// derived the working read key at the gate — so the two accelerator sources are
110	/// checked against it, not against each other.
111	pub fn cross_check(
112	    owner_blob_seed: &[u8; 32],
113	    ascent_link_seed: Option<&[u8; 32]>,
114	    unseal_seed: &[u8; 32],
115	    epoch: u64,
116	) -> OwnerEntry {
117	    if !ct_eq_32(owner_blob_seed, unseal_seed) {
118	        return OwnerEntry::Abuse(AbuseEvent {
119	            description: "owner-blob seed disagrees with the unsealed scope seed".to_string(),
120	        });
121	    }
122	    if let Some(ascent) = ascent_link_seed {
123	        if !ct_eq_32(ascent, unseal_seed) {
124	            return OwnerEntry::Abuse(AbuseEvent {
125	                description: "ascent-link seed disagrees with the unsealed scope seed".to_string(),
126	            });
127	        }
128	    }
129	    OwnerEntry::Confirmed {
130	        seed: *unseal_seed,
131	        epoch,
132	    }
133	}
